    "monitor": "Monitoring",
    "monitor_short": "Monitor",
    "monitor_full": "Monitoring",
    "monitor_desc": "<b>Monitoring.</b> Unlocks the live METRICS dashboard and alerts.",
    "monitor_desc_long": "Collects utilization, queue depth, error rate and latency from every service and raises alerts before overloads become outages. Never receives traffic \u2014 place it anywhere. Real-world equivalents: AWS CloudWatch \xB7 Azure Monitor \xB7 Google Cloud Operations.",
    "monitor_flow": "Flow: standalone \u2014 no connections; watches every service",
    "monitor_desc_short": "Live metrics + alerts ($75)",
    "tip_monitor": "Place a Monitoring service \u2014 you can't fix what you can't see",
    "metrics": "Metrics",
    "metrics_locked": "Place a Monitoring service to unlock live metrics.",
    "metrics_locked_providers": "Real-world equivalents: AWS CloudWatch \xB7 Azure Monitor \xB7 Google Cloud Operations.",
    "metrics_locked_teach": "You can't fix what you can't see.",
    "metrics_col_util": "Util",
    "metrics_col_queue": "Queue",
    "metrics_col_err": "Err",
    "metrics_col_lat": "Lat",
