    // -- Level 20: Two Regions --
    "level_20_title": "\u53CC\u533A\u57DF",
    "level_20_scenario": "\u4F60\u7684\u670D\u52A1\u8D70\u5411\u4E86\u5168\u7403\uFF0C\u8FD0\u7EF4\u4E5F\u6392\u597D\u4E86\u8BC1\u660E\u5B83\u7684\u6F14\u7EC3\uFF1A\u5F00\u5C40 35 \u79D2\u540E\uFF0C\u4F60 GeoDNS \u540E\u9762\u90A3\u6574\u5957\u9884\u5EFA\u6808\u2014\u2014\u9632\u706B\u5899\u3001\u8D1F\u8F7D\u5747\u8861\u5668\u3001\u8BA1\u7B97\u8282\u70B9\u2014\u2014\u5C06\u7184\u706D 25 \u79D2\u3002\u5168\u90E8\u6D41\u91CF\u4E0D\u80FD\u6258\u4ED8\u7ED9\u5355\u4E2A\u533A\u57DF\u3002\u8D81\u706F\u8FD8\u4EAE\uFF0C\u628A\u7B2C\u4E8C\u4E2A\u533A\u57DF\u5EFA\u51FA\u6765\u3002",
    "level_20_learn": "GeoDNS \u53EA\u4F1A\u89E3\u6790\u5230\u8FD8\u6D3B\u7740\u7684\u524D\u95E8\uFF0C\u6240\u4EE5\u63A5\u5728\u5B83\u4E0A\u9762\u7684\u7B2C\u4E8C\u5957\u5B8C\u6574\u6808\u300C\u5C31\u662F\u300D\u4F60\u7684\u6545\u969C\u8F6C\u79FB\uFF1AA \u533A\u57DF\u4E00\u7184\u706D\uFF0C\u6D41\u91CF\u5F53\u5373\u5207\u6362\u8FC7\u53BB\uFF1B\u5B83\u6062\u590D\u540E\uFF0C\u6D41\u91CF\u53C8\u81EA\u884C\u91CD\u65B0\u94FA\u5F00\u3002\u8FD9\u5C31\u662F\u53CC\u6D3B\u2014\u2014\u4E24\u4E2A\u533A\u57DF\u90FD\u627F\u63A5\u5B9E\u65F6\u6D41\u91CF\uFF0C\u4EFB\u610F\u4E00\u4E2A\u90FD\u80FD\u625B\u8D77\u6574\u4E2A\u7AD9\u70B9\u3002\u5751\u5728\u8D26\u5355\u4E0A\uFF1A\u4EC0\u4E48\u90FD\u8981\u4E24\u4EFD\uFF0C\u610F\u5473\u7740\u4E0D\u7BA1\u6709\u6CA1\u6709\u6545\u969C\uFF0C\u6BCF\u4E00\u79D2\u90FD\u5728\u4ED8\u53CC\u500D\u7EF4\u62A4\u8D39\u3002",
    "level_20_debrief": "\u53CC\u6D3B\u610F\u5473\u7740\u4EFB\u4F55\u4E00\u4E2A\u533A\u57DF\u90FD\u5931\u53BB\u5F97\u8D77\u53E6\u4E00\u4E2A\u2014\u2014\u4F60\u521A\u5728\u4E24\u4E2A\u65B9\u5411\u4E0A\u90FD\u8BC1\u660E\u4E86\u8FD9\u4E00\u70B9\uFF0C\u4E5F\u5168\u7A0B\u4ED8\u4E86\u53CC\u500D\u7EF4\u62A4\u8D39\uFF1B\u90A3\u4E2A\u770B\u4F3C\u95F2\u7F6E\u7684\u7B2C\u4E8C\u533A\u57DF\u300C\u5C31\u662F\u300D\u4EA7\u54C1\u672C\u8EAB\u3002\u4E3B\u5907\uFF08active-passive\uFF09\u7528\u51B7\u5907\u628A\u8D26\u5355\u780D\u534A\uFF0C\u4EE3\u4EF7\u662F\u5207\u6362\u65F6\u95F4\u548C\u4E00\u4E2A\u4ECE\u6CA1\u88AB\u9A8C\u8BC1\u8FC7\u7684\u533A\u57DF\u3002Route 53 \u5065\u5EB7\u68C0\u67E5 \xB7 Azure Traffic Manager \xB7 Cloud DNS\u2014\u2014\u540C\u6837\u7684\u9009\u62E9\uFF0C\u540C\u6837\u7684\u53CC\u500D\u8D26\u5355\u3002",
    "obj_20_survived_region": "\u625B\u8FC7\u533A\u57DF\u6545\u969C\u4E14\u58F0\u8A89\u9AD8\u4E8E 70%",
    "obj_20_serve_300": "\u5B8C\u6210 300 \u4E2A\u8BF7\u6C42",
    "obj_20_outage_throughput": "\u5728 A \u533A\u57DF\u7184\u706D\u671F\u95F4\u5B8C\u6210 60 \u4E2A\u8BF7\u6C42",
