    // -- Level 21: Hello, GPU --
    "level_21_title": "\u4F60\u597D\uFF0CGPU",
    "level_21_scenario": "\u4EA7\u54C1\u90E8\u4E0A\u7EBF\u4E86 AI \u529F\u80FD\uFF0C\u5982\u4ECA 60% \u7684\u6D41\u91CF\u662F\u63A8\u7406\u3002\u80FD\u5904\u7406\u5B83\u7684\u53EA\u6709 GPU\u2014\u2014\u800C\u5E02\u573A\u90E8\u521A\u5B98\u5BA3\u4E86\u53D1\u5E03\u65E5\u72C2\u6F6E\uFF0C\u4ECE\u7B2C 45 \u79D2\u8D77\u4E00\u6CE2\u6CE2\u88AD\u6765\u3002\u5148\u8BA9\u4E00\u4E2A\u6A21\u578B\u8DD1\u8D77\u6765\u5BF9\u5916\u670D\u52A1\uFF0C\u5E76\u8D76\u5728\u6D6A\u6F6E\u6253\u6765\u4E4B\u524D\u628A\u66F4\u5927\u7684\u90A3\u4E2A\u52A0\u8F7D\u597D\u3002",
    "level_21_learn": "GPU \u96C6\u7FA4\u53EA\u5904\u7406 INFERENCE\uFF0C\u800C\u4E14\u6709\u51B7\u542F\u52A8\uFF1A\u6A21\u578B\u8981\u52A0\u8F7D 12-30 \u79D2\uFF0C\u4E4B\u540E\u8282\u70B9\u624D\u5F00\u59CB\u63A5\u6D41\u91CF\u3002\u7B49\u7EA7\u5373\u6A21\u578B\u5927\u5C0F\u2014\u2014\u6279\u6B21\u66F4\u5927\uFF0C\u56DE\u7B54\u4E5F\u66F4\u597D\uFF08\u7B54\u9519\u98CE\u9669 10% \u2192 4% \u2192 1%\uFF09\u2014\u2014\u4F46\u6BCF\u6B21\u5347\u7EA7\u90FD\u4F1A\u300C\u91CD\u65B0\u52A0\u8F7D\u300D\u6A21\u578B\uFF0C\u800C\u91CD\u8F7D\u4E2D\u7684 GPU \u4EC0\u4E48\u4E5F\u5904\u7406\u4E0D\u4E86\u3002\u5347\u7EA7\u8981\u6311\u4F4E\u8C37\uFF1B\u5728\u6D6A\u6F6E\u91CC\u5347\u7EA7\uFF0C\u7B49\u4E8E\u4EB2\u624B\u7ED9\u81EA\u5DF1\u5236\u9020\u4E00\u6B21\u6545\u969C\u3002",
    "level_21_debrief": "\u6A21\u578B\u52A0\u8F7D\u6B63\u662F\u63A8\u7406\u673A\u7FA4\u8981\u9884\u70ED\u7684\u539F\u56E0\uFF1AAWS P5 / Inferentia\u3001Azure ND\u3001GCP A3 / TPU\u2014\u2014\u6BCF\u5BB6\u4E91\u5382\u5546\u90FD\u4ECE\u5F00\u673A\u90A3\u4E00\u523B\u8D77\u7ED9 GPU \u8BA1\u8D39\uFF0C\u800C\u7528\u6237\u8981\u7B49\u6743\u91CD\u8FDB\u4E86\u663E\u5B58\u624D\u89C1\u5F97\u5230\u5B83\u3002\u66F4\u5927\u7684\u6A21\u578B\u8981\u5728\u53D1\u5E03\u300C\u4E4B\u524D\u300D\u88C5\u597D\uFF0C\u7EDD\u4E0D\u8981\u5728\u53D1\u5E03\u5F53\u4E2D\u3002",
    "obj_21_serve_80_inference": "\u5904\u7406 80 \u4E2A INFERENCE \u8BF7\u6C42",
    "obj_21_rep_above_65": "\u58F0\u8A89\u9AD8\u4E8E 65%",
    "obj_21_few_bad_answers": "\u7B54\u9519\u5C11\u4E8E 6 \u6B21",
