    "report_late": "{n} en retard",
    "hint_gpu_inference": "La demande d'IA \xE9merge \u2014 le trafic INFERENCE a besoin d'un cluster GPU.",
    "gpu_batch_fill": "Lot : {n}/{size}",
    "gpu_bad_answers": "Mauvaises r\xE9ponses : {n} (risque {pct}%)",
