    // Achievements (#158): Trophies panel + unlock toasts.
    "trophies": "Troph\xE9es",
    "trophies_title": "TROPH\xC9ES",
    "ach_unlocked": "Succ\xE8s d\xE9bloqu\xE9",
    "ach_first_win_name": "Premi\xE8re victoire",
