    "tip_db": "\uB370\uC774\uD130\uBCA0\uC774\uC2A4 \uB178\uB4DC\uB97C \uB354 \uCD94\uAC00\uD558\uAC70\uB098 \uAE30\uC874 \uAC83\uC744 \uC5C5\uADF8\uB808\uC774\uB4DC\uD558\uC138\uC694",
    "tip_cache": "\uCE90\uC2DC\uB97C \uC0AC\uC6A9\uD574 \uB370\uC774\uD130\uBCA0\uC774\uC2A4 \uBD80\uD558\uB97C \uC904\uC774\uC138\uC694",
