    "tip_repair": "\uC0C1\uD0DC \uD328\uB110\uC744 \uBAA8\uB2C8\uD130\uB9C1\uD558\uACE0 \uC190\uC0C1\uB41C \uC11C\uBE44\uC2A4\uB97C \uC218\uB9AC\uD558\uC138\uC694",
    "tip_upkeep_high": "\uC720\uC9C0 \uBE44\uC6A9\uC774 \uC218\uC785\uC5D0 \uBE44\uD574 \uB108\uBB34 \uB192\uC558\uC2B5\uB2C8\uB2E4",
