    "campaign_briefing_back": "\u041D\u0430\u0437\u0430\u0434",
    "campaign_complete": "\u0423\u0420\u041E\u0412\u0415\u041D\u042C \u041F\u0420\u041E\u0419\u0414\u0415\u041D",
