    "tip_waf": "\u0907\u0928\u094D\u091F\u0930\u0928\u0947\u091F\u0938\u0901\u0917 \u091C\u094B\u0921\u093F\u090F\u0915\u094B Firewall \u0930\u093E\u0916\u094D\u0928\u0941\u0939\u094B\u0938\u094D, \u0924\u093E\u0915\u093F \u0916\u0930\u093E\u092C \u091F\u094D\u0930\u093E\u092B\u093F\u0915 \u0924\u092A\u093E\u0908\u0902\u0915\u094B \u0938\u0947\u0935\u093E\u092E\u093E \u092A\u0941\u0917\u094D\u0928\u0941\u0905\u0918\u093F \u0928\u0948 \u0930\u094B\u0915\u093F\u092F\u094B\u0938\u094D\u0964",
    "tip_multiple_waf": "\u0920\u0942\u0932\u094B \u0906\u0915\u094D\u0930\u092E\u0923 \u091B\u093E\u0932\u093E\u0939\u0930\u0942 \u0939\u094D\u092F\u093E\u0928\u094D\u0921\u0932 \u0917\u0930\u094D\u0928 \u092C\u0939\u0941\u0935\u093F\u0927 \u092B\u093E\u092F\u0930\u0935\u093E\u0932\u0939\u0930\u0942 \u0921\u093F\u092A\u094D\u0932\u0947 \u0917\u0930\u094D\u0928\u0941\u0939\u094B\u0938\u094D",
