    "asg_warming": "+{n} \u0924\u092F\u093E\u0930 \u0939\u0941\u0901\u0926\u0948",
    "asg_enable_tip": "\u092F\u094B \u0915\u092E\u094D\u092A\u094D\u092F\u0941\u091F \u0928\u094B\u0921\u092E\u093E \u0905\u091F\u094B-\u0938\u094D\u0915\u0947\u0932\u093F\u0919 \u0938\u0915\u094D\u0930\u093F\u092F \u0917\u0930\u094D\u0928\u0941\u0939\u094B\u0938\u094D",
    "asg_disable_tip": "\u0905\u091F\u094B-\u0938\u094D\u0915\u0947\u0932\u093F\u0919 \u0928\u093F\u0937\u094D\u0915\u094D\u0930\u093F\u092F \u0917\u0930\u094D\u0928\u0941\u0939\u094B\u0938\u094D (\u090F\u0909\u091F\u0948 \u0907\u0928\u094D\u0938\u094D\u091F\u0947\u0928\u094D\u0938\u092E\u093E \u092B\u0930\u094D\u0915\u093F\u0928\u094D\u091B)",
    "hint_enable_asg": "\u092F\u094B \u0915\u092E\u094D\u092A\u094D\u092F\u0941\u091F \u0928\u094B\u0921 \u0915\u0947\u0939\u0940 \u092C\u0947\u0930\u0926\u0947\u0916\u093F \u092A\u0942\u0930\u094D\u0923 \u092D\u093E\u0930\u092E\u093E \u091B\u0964 \u0932\u094B\u0921 \u0905\u0928\u0941\u0938\u093E\u0930 \u092C\u0922\u094D\u0928 AUTO \u0938\u0915\u094D\u0930\u093F\u092F \u0917\u0930\u094D\u0928\u0941\u0939\u094B\u0938\u094D\u0964",
