    // -- Level 1: The First Server --
    "level_1_title": "\u092A\u0939\u093F\u0932\u094B \u0938\u0930\u094D\u092D\u0930",
    "level_1_scenario": "\u0924\u092A\u093E\u0908\u0902 \u090F\u0915\u0926\u092E\u0948 \u0928\u092F\u093E\u0901 \u0935\u0947\u092C \u0938\u0947\u0935\u093E \u0938\u0941\u0930\u0941 \u0917\u0930\u094D\u0926\u0948 \u0939\u0941\u0928\u0941\u0939\u0941\u0928\u094D\u091B\u0964 \u0906\u0927\u093E\u0930\u092D\u0942\u0924 \u092A\u093E\u0907\u092A\u0932\u093E\u0907\u0928 \u092C\u0928\u093E\u0909\u0928\u0941\u0939\u094B\u0938\u094D: \u0907\u0928\u094D\u091F\u0930\u0928\u0947\u091F \u2192 \u092B\u093E\u092F\u0930\u0935\u093E\u0932 \u2192 \u0932\u094B\u0921 \u092C\u094D\u092F\u093E\u0932\u0947\u0928\u094D\u0938\u0930 \u2192 \u0915\u092E\u094D\u092A\u094D\u092F\u0941\u091F \u2192 \u0921\u093E\u091F\u093E\u092C\u0947\u0938\u0964",
    "level_1_learn": "\u0939\u0930\u0947\u0915 \u0905\u0928\u0941\u0930\u094B\u0927 \u0909\u0939\u0940 \u0936\u0943\u0919\u094D\u0916\u0932\u093E\u092C\u093E\u091F \u092C\u0917\u094D\u091B\u0964 \u092B\u093E\u092F\u0930\u0935\u093E\u0932\u0932\u0947 \u0906\u0915\u094D\u0930\u092E\u0923\u0939\u0930\u0942 \u0905\u0935\u0930\u0941\u0926\u094D\u0927 \u0917\u0930\u094D\u091B, \u0932\u094B\u0921 \u092C\u094D\u092F\u093E\u0932\u0947\u0928\u094D\u0938\u0930\u0932\u0947 \u0915\u093E\u092E \u0935\u093F\u0924\u0930\u0923 \u0917\u0930\u094D\u091B, \u0915\u092E\u094D\u092A\u094D\u092F\u0941\u091F\u0932\u0947 \u092A\u094D\u0930\u0936\u094B\u0927\u0928 \u0917\u0930\u094D\u091B, \u0930 \u0921\u093E\u091F\u093E\u092C\u0947\u0938\u0932\u0947 \u0921\u093E\u091F\u093E \u0938\u094D\u0925\u093E\u092F\u0940 \u0930\u0942\u092A\u092E\u093E \u0930\u093E\u0916\u094D\u091B\u0964",
    "level_1_debrief": "\u092B\u093E\u092F\u0930\u0935\u093E\u0932 \u0935\u0948\u0915\u0932\u094D\u092A\u093F\u0915 \u0939\u094B\u0907\u0928 \u2014 MALICIOUS \u091F\u094D\u0930\u093E\u092B\u093F\u0915\u0932\u0947 \u092A\u094D\u0930\u0924\u093F\u0937\u094D\u0920\u093E \u091B\u093F\u091F\u0948 \u0928\u0937\u094D\u091F \u0917\u0930\u094D\u091B\u0964 \u092F\u0938\u0932\u093E\u0908 \u0938\u0927\u0948\u0901 \u0938\u092C\u0948\u092D\u0928\u094D\u0926\u093E \u0905\u0917\u093E\u0921\u093F \u0930\u093E\u0916\u094D\u0928\u0941\u0939\u094B\u0938\u094D\u0964",
