    "campaign_select_title": "\u041A\u0410\u041C\u041F\u0410\u041D\u0406\u042F",
    "campaign_briefing_start": "\u041F\u043E\u0447\u0430\u0442\u0438 \u0440\u0456\u0432\u0435\u043D\u044C",
