    "campaign_chapter_2": "\u0420\u043E\u0437\u0434\u0456\u043B 2: \u041E\u043F\u0442\u0438\u043C\u0456\u0437\u0430\u0446\u0456\u044F",
    "campaign_chapter_3": "\u0420\u043E\u0437\u0434\u0456\u043B 3: \u0417\u0430\u0445\u0438\u0441\u0442 \u0456 \u043C\u0430\u0439\u0441\u0442\u0435\u0440\u043D\u0456\u0441\u0442\u044C",
    "campaign_chapter_4": "\u0420\u043E\u0437\u0434\u0456\u043B 4: \u0413\u043E\u0442\u043E\u0432\u043D\u0456\u0441\u0442\u044C \u0434\u043E \u043F\u0440\u043E\u0434\u0430\u043A\u0448\u0435\u043D\u0443",
    "campaign_chapter_5": "\u0420\u043E\u0437\u0434\u0456\u043B 5: \u0425\u0432\u0438\u043B\u044F AI",
    "campaign_locked": "\u0417\u0430\u0431\u043B\u043E\u043A\u043E\u0432\u0430\u043D\u043E",
    "monitor": "\u041C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433",
    "monitor_short": "\u041C\u043E\u043D\u0456\u0442\u043E\u0440",
    "monitor_full": "\u041C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433",
    "monitor_desc": "<b>\u041C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433.</b> \u0412\u0456\u0434\u043A\u0440\u0438\u0432\u0430\u0454 \u0436\u0438\u0432\u0438\u0439 \u0434\u0430\u0448\u0431\u043E\u0440\u0434 \u041C\u0415\u0422\u0420\u0418\u041A \u0456 \u0430\u043B\u0435\u0440\u0442\u0438.",
    "monitor_desc_long": "\u0417\u0431\u0438\u0440\u0430\u0454 \u0443\u0442\u0438\u043B\u0456\u0437\u0430\u0446\u0456\u044E, \u0433\u043B\u0438\u0431\u0438\u043D\u0443 \u0447\u0435\u0440\u0433\u0438, \u0447\u0430\u0441\u0442\u043A\u0443 \u043F\u043E\u043C\u0438\u043B\u043E\u043A \u0456 \u0437\u0430\u0442\u0440\u0438\u043C\u043A\u0443 \u0437 \u043A\u043E\u0436\u043D\u043E\u0433\u043E \u0441\u0435\u0440\u0432\u0456\u0441\u0443 \u0442\u0430 \u043F\u0456\u0434\u043D\u0456\u043C\u0430\u0454 \u0430\u043B\u0435\u0440\u0442\u0438, \u043F\u043E\u043A\u0438 \u043F\u0435\u0440\u0435\u0432\u0430\u043D\u0442\u0430\u0436\u0435\u043D\u043D\u044F \u043D\u0435 \u043F\u0435\u0440\u0435\u0440\u043E\u0441\u043B\u043E \u0443 \u0432\u0456\u0434\u043C\u043E\u0432\u0443. \u0422\u0440\u0430\u0444\u0456\u043A \u043D\u0435 \u043F\u0440\u0438\u0439\u043C\u0430\u0454 \u2014 \u0441\u0442\u0430\u0432 \u0431\u0443\u0434\u044C-\u0434\u0435. \u0420\u0435\u0430\u043B\u044C\u043D\u0456 \u0430\u043D\u0430\u043B\u043E\u0433\u0438: AWS CloudWatch \xB7 Azure Monitor \xB7 Google Cloud Operations.",
    "monitor_flow": "\u041F\u043E\u0442\u0456\u043A: \u0441\u0430\u043C \u043F\u043E \u0441\u043E\u0431\u0456 \u2014 \u0431\u0435\u0437 \u0437\u02BC\u0454\u0434\u043D\u0430\u043D\u044C; \u0441\u0442\u0435\u0436\u0438\u0442\u044C \u0437\u0430 \u043A\u043E\u0436\u043D\u0438\u043C \u0441\u0435\u0440\u0432\u0456\u0441\u043E\u043C",
    "monitor_desc_short": "\u0416\u0438\u0432\u0456 \u043C\u0435\u0442\u0440\u0438\u043A\u0438 + \u0430\u043B\u0435\u0440\u0442\u0438 ($75)",
    "tip_monitor": "\u041F\u043E\u0441\u0442\u0430\u0432 \u0441\u0435\u0440\u0432\u0456\u0441 \u041C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433\u0443 \u2014 \u043D\u0435 \u043F\u043E\u043B\u0430\u0433\u043E\u0434\u0438\u0448 \u0442\u0435, \u0447\u043E\u0433\u043E \u043D\u0435 \u0431\u0430\u0447\u0438\u0448",
    "metrics": "\u041C\u0435\u0442\u0440\u0438\u043A\u0438",
    "metrics_locked": "\u041F\u043E\u0441\u0442\u0430\u0432 \u0441\u0435\u0440\u0432\u0456\u0441 \u041C\u043E\u043D\u0456\u0442\u043E\u0440\u0438\u043D\u0433\u0443, \u0449\u043E\u0431 \u0432\u0456\u0434\u043A\u0440\u0438\u0442\u0438 \u0436\u0438\u0432\u0456 \u043C\u0435\u0442\u0440\u0438\u043A\u0438.",
    "metrics_locked_providers": "\u0420\u0435\u0430\u043B\u044C\u043D\u0456 \u0430\u043D\u0430\u043B\u043E\u0433\u0438: AWS CloudWatch \xB7 Azure Monitor \xB7 Google Cloud Operations.",
    "metrics_locked_teach": "\u041D\u0435 \u043F\u043E\u043B\u0430\u0433\u043E\u0434\u0438\u0448 \u0442\u0435, \u0447\u043E\u0433\u043E \u043D\u0435 \u0431\u0430\u0447\u0438\u0448.",
