    "fail_gpu_only": "GPU \u043E\u0431\u0441\u043B\u0443\u0433\u043E\u0432\u0443\u044E\u0442\u044C \u043B\u0438\u0448\u0435 \u0456\u043D\u0444\u0435\u0440\u0435\u043D\u0441",
    "soft_bad_answer": "\u041F\u043E\u0433\u0430\u043D\u0430 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u044C",
    "soft_slow": "\u041F\u043E\u0432\u0456\u043B\u044C\u043D\u043E",
    "goodput_label": "\u0413\u0423\u0414\u041F\u0423\u0422 (30 \u0441)",
    "goodput_hint": "\u0427\u0430\u0441\u0442\u043A\u0430 \u043F\u043E\u043F\u0438\u0442\u0443 \u0437\u0430 \u043E\u0441\u0442\u0430\u043D\u043D\u0456 30 \u0441\u0435\u043A\u0443\u043D\u0434, \u044F\u043A\u0443 \u0432\u0441\u0442\u0438\u0433\u043B\u0438 \u043E\u0431\u0441\u043B\u0443\u0436\u0438\u0442\u0438, \u043F\u043E\u043A\u0438 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u044C \u0449\u0435 \u0431\u0443\u043B\u0430 \u043A\u043E\u043C\u0443\u0441\u044C \u043F\u043E\u0442\u0440\u0456\u0431\u043D\u0430. \u041D\u0430 \u0432\u0456\u0434\u043C\u0456\u043D\u0443 \u0432\u0456\u0434 \u0440\u0435\u043F\u0443\u0442\u0430\u0446\u0456\u0457, \u0432\u043E\u043D\u0430 \u043D\u0435 \u043C\u043E\u0436\u0435 \u0442\u0440\u0438\u043C\u0430\u0442\u0438\u0441\u044F \u043D\u0430 100% \u043B\u0438\u0448\u0435 \u0442\u043E\u043C\u0443, \u0449\u043E \u043D\u0456\u0447\u043E\u0433\u043E \u043D\u0435 \u0432\u0456\u0434\u0431\u0443\u0432\u0430\u0454\u0442\u044C\u0441\u044F.",
    "replay_tutorial": "\u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0438 \u0442\u0443\u0442\u043E\u0440\u0456\u0430\u043B",
    "report_title": "\u0429\u043E \u0441\u0442\u0430\u043B\u043E\u0441\u044F",
