    "report_top_failures": "\u041D\u0430\u0439\u0447\u0430\u0441\u0442\u0456\u0448\u0456 \u0437\u0431\u043E\u0457",
    "report_none": "\u043D\u0435\u043C\u0430\u0454",
    "report_served": "\u0412\u0447\u0430\u0441\u043D\u043E \u043E\u0431\u0440\u043E\u0431\u043B\u0435\u043D\u043E {onTime} \u0437 {total} ({pct}%)",
